"use client"

import * as React from "react"

import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  CONNECTED_APPS,
  NOW,
  TOKENS,
  type ConnectedApp,
  type Token,
} from "@/lib/mockups/connected-apps-data"
import { AppDetail } from "@/components/mockups/connected-apps/app-detail"
import { AppsOverview } from "@/components/mockups/connected-apps/apps-overview"

type Preview = "populated" | "first-run"

export default function ConnectedAppsPage() {
  const [preview, setPreview] = React.useState<Preview>("populated")
  const [openAppId, setOpenAppId] = React.useState<string | null>(null)
  const [apps, setApps] = React.useState<ConnectedApp[]>(CONNECTED_APPS)
  const [tokens, setTokens] = React.useState<Token[]>(TOKENS)

  const openApp = apps.find((app) => app.id === openAppId) ?? null

  function switchPreview(next: Preview) {
    setPreview(next)
    setOpenAppId(null)
    setApps(next === "populated" ? CONNECTED_APPS : [])
    setTokens(next === "populated" ? TOKENS : [])
  }

  function createApp(app: ConnectedApp) {
    setApps((previous) => [...previous, app])
    setOpenAppId(app.id)
  }

  function revoke(token: Token) {
    setTokens((previous) =>
      previous.map((entry) =>
        entry.id === token.id ? { ...entry, revokedAt: NOW } : entry,
      ),
    )
  }

  return (
    <MockupShell
      actions={
        <>
          <span className="text-xs text-muted-foreground">Preview</span>
          <ToggleGroup
            onValueChange={(value) => {
              if (value) switchPreview(value as Preview)
            }}
            size="sm"
            type="single"
            value={preview}
            variant="outline"
          >
            <ToggleGroupItem value="populated">Populated</ToggleGroupItem>
            <ToggleGroupItem value="first-run">First run</ToggleGroupItem>
          </ToggleGroup>
        </>
      }
      eyebrow="Integrations"
      title="Design custom integrations access token management flows"
    >
      <AppShell
        active="Integrations"
        breadcrumb={openApp ? openApp.name : "Integrations"}
        onNavigate={(title) => {
          if (title === "Integrations") setOpenAppId(null)
        }}
      >
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          {openApp ? (
            <AppDetail
              app={openApp}
              onBack={() => setOpenAppId(null)}
              onCreated={(token) =>
                setTokens((previous) => [...previous, token])
              }
              onRevoke={revoke}
              tokens={tokens}
            />
          ) : (
            <AppsOverview
              apps={apps}
              onCreate={createApp}
              onOpen={setOpenAppId}
              tokens={tokens}
            />
          )}
        </div>
      </AppShell>
    </MockupShell>
  )
}

"use client"

import * as React from "react"

import { toast } from "sonner"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import {
  formatDate,
  mintSecret,
  NOW,
  prefixOf,
  READ_ONLY_SCOPES,
  scopeSummary,
  type ConnectedApp,
  type Permission,
  type Token,
} from "@/lib/mockups/connected-apps-data"
import { ScopePicker } from "@/components/mockups/connected-apps/scope-picker"
import {
  CopiedIcon,
  CopyTokenIcon,
  NearExpiryIcon,
} from "@/components/mockups/connected-apps/icons"

const EXPIRY_CHOICES = [
  { days: 30, id: "30", label: "In 30 days" },
  { days: 60, id: "60", label: "In 60 days" },
  { days: 90, id: "90", label: "In 90 days" },
  { days: 365, id: "365", label: "In a year" },
]

const NEVER = "never"

function expiryFrom(choice: string): string | null {
  const option = EXPIRY_CHOICES.find((entry) => entry.id === choice)
  if (!option) return null
  return new Date(
    new Date(NOW).getTime() + option.days * 86_400_000,
  ).toISOString()
}

export function CreateTokenDialog({
  app,
  onCreated,
  onOpenChange,
  open,
}: {
  app: ConnectedApp
  onCreated: (token: Token) => void
  onOpenChange: (open: boolean) => void
  open: boolean
}) {
  /* Lifted into the shell so the scrim, Escape and close button all route through one check. */
  const [locked, setLocked] = React.useState(false)
  const guard = React.useRef<() => void>(() => onOpenChange(false))

  /* Stable identities: the body registers its guard from an effect. */
  const close = React.useCallback(() => onOpenChange(false), [onOpenChange])
  const registerGuard = React.useCallback(
    (locking: boolean, requestClose: () => void) => {
      setLocked(locking)
      guard.current = requestClose
    },
    [],
  )

  return (
    <Dialog
      onOpenChange={(next) => {
        if (!next && locked) {
          guard.current()
          return
        }
        onOpenChange(next)
      }}
      open={open}
    >
      <DialogContent
        className="sm:max-w-lg"
        onEscapeKeyDown={(event) => {
          if (!locked) return
          event.preventDefault()
          guard.current()
        }}
        onInteractOutside={(event) => {
          if (locked) event.preventDefault()
        }}
        onPointerDownOutside={(event) => {
          if (locked) event.preventDefault()
        }}
        showCloseButton={!locked}
      >
        {/* Keyed on the app so every open starts clean and the secret unmounts with it. */}
        <CreateTokenBody
          app={app}
          key={app.id}
          onClose={close}
          onCreated={onCreated}
          onGuardChange={registerGuard}
        />
      </DialogContent>
    </Dialog>
  )
}

type Phase = "form" | "creating" | "revealed" | "confirm-close"

function CreateTokenBody({
  app,
  onClose,
  onCreated,
  onGuardChange,
}: {
  app: ConnectedApp
  onClose: () => void
  onCreated: (token: Token) => void
  onGuardChange: (locked: boolean, requestClose: () => void) => void
}) {
  const [phase, setPhase] = React.useState<Phase>("form")
  const [name, setName] = React.useState("")
  const [scopes, setScopes] = React.useState<Permission[]>(READ_ONLY_SCOPES)
  const [expiry, setExpiry] = React.useState("90")
  const [secret, setSecret] = React.useState("")
  const [copied, setCopied] = React.useState(false)

  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined,
  )
  React.useEffect(() => () => clearTimeout(timer.current), [])

  /* Sealed from when the secret appears until answered, confirm step included. "Close anyway" calls onClose directly. */
  const locked = phase === "revealed" || phase === "confirm-close"
  React.useEffect(() => {
    onGuardChange(locked, () => {
      if (copied) onClose()
      else setPhase("confirm-close")
    })
  }, [copied, locked, onClose, onGuardChange])

  const expiresAt = expiryFrom(expiry)
  const canSave = name.trim().length > 0 && scopes.length > 0

  function create() {
    setPhase("creating")

    window.setTimeout(() => {
      const value = mintSecret()
      setSecret(value)
      setPhase("revealed")
      onCreated({
        appId: app.id,
        createdAt: NOW,
        createdBy: "Nawaf Al-Harbi",
        expiresAt,
        id: `tok-${prefixOf(value)}`,
        lastUsedAt: null,
        name: name.trim(),
        prefix: prefixOf(value),
        revokedAt: null,
        scopes,
      })
    }, 700)
  }

  async function copySecret() {
    try {
      await navigator.clipboard.writeText(secret)
      setCopied(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 2000)
      toast.success("Access token copied", { description: name.trim() })
    } catch {
      /* Clipboard can be blocked or unavailable; the secret is unrecoverable, so it goes into the toast. */
      toast.error("Could not reach the clipboard", { description: secret })
    }
  }

  function attemptClose() {
    if (copied) {
      onClose()
      return
    }
    setPhase("confirm-close")
  }

  if (phase === "confirm-close") {
    return (
      <>
        <DialogHeader>
          <DialogTitle>Close without copying the token?</DialogTitle>
          <DialogDescription>
            This is the only time the secret is shown. Close now and it cannot
            be recovered — the token stays live, so the only way back is to
            revoke it and create another.
          </DialogDescription>
        </DialogHeader>

        <DialogFooter>
          <Button onClick={() => setPhase("revealed")} variant="outline">
            Back to the token
          </Button>
          <Button onClick={onClose} variant="destructive">
            Close anyway
          </Button>
        </DialogFooter>
      </>
    )
  }

  if (phase === "revealed") {
    return (
      <>
        <DialogHeader>
          <DialogTitle>Your new access token has been created</DialogTitle>
          <DialogDescription>
            Make sure to copy this token now. You will not be able to see it
            again.
          </DialogDescription>
        </DialogHeader>

        <Alert className="bg-warning-tint text-warning-tint-foreground">
          <NearExpiryIcon />
          <AlertDescription className="text-warning-tint-foreground">
            Sarj stores only a hash of this value. Nobody can show it to you a
            second time — not you, not support.
          </AlertDescription>
        </Alert>

        {/* readOnly, not disabled, so it stays focusable and selectable. LTR so base64 is not reordered. */}
        <InputGroup>
          <InputGroupInput
            aria-label="Access token"
            className="font-mono"
            dir="ltr"
            onCopy={() => setCopied(true)}
            onFocus={(event) => event.currentTarget.select()}
            readOnly
            value={secret}
          />
          <InputGroupAddon align="inline-end">
            <InputGroupButton onClick={copySecret}>
              {copied ? <CopiedIcon /> : <CopyTokenIcon />}
              {copied ? "Copied" : "Copy"}
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>

        <p className="text-sm text-muted-foreground">
          <span dir="auto">{name.trim()}</span> · {scopeSummary(scopes)} ·{" "}
          {expiresAt ? `Expires ${formatDate(expiresAt)}` : "Never expires"}
        </p>

        <DialogFooter>
          {/* Never gated on having copied: a blocked clipboard would trap the reader. */}
          <Button onClick={attemptClose}>Done</Button>
        </DialogFooter>
      </>
    )
  }

  return (
    <>
      <DialogHeader>
        <DialogTitle>New access token</DialogTitle>
        <DialogDescription>
          This creates a live token for <span dir="auto">{app.name}</span>{" "}
          immediately. The full secret is shown only once, so be ready to copy
          it.
        </DialogDescription>
      </DialogHeader>

      <div className="-mx-1 flex max-h-[60vh] flex-col gap-4 overflow-y-auto px-1">
        <Field>
          <FieldLabel htmlFor="token-name">Name</FieldLabel>
          <Input
            dir="auto"
            id="token-name"
            onChange={(event) => setName(event.target.value)}
            placeholder="Production sync"
            value={name}
          />
          <FieldDescription>
            Name it for where it runs, so you know which one to revoke.
          </FieldDescription>
        </Field>

        <ScopePicker onChange={setScopes} scopes={scopes} />

        <Field>
          <FieldLabel htmlFor="token-expiry">Expires</FieldLabel>
          <Select onValueChange={setExpiry} value={expiry}>
            <SelectTrigger id="token-expiry">
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              {EXPIRY_CHOICES.map((option) => (
                <SelectItem key={option.id} value={option.id}>
                  {option.label}
                </SelectItem>
              ))}
              <SelectSeparator />
              <SelectItem value={NEVER}>No expiry</SelectItem>
            </SelectContent>
          </Select>
          <FieldDescription>
            {expiresAt
              ? `Stops working on ${formatDate(expiresAt)}.`
              : "It keeps working until someone revokes it."}
          </FieldDescription>
        </Field>
      </div>

      <DialogFooter>
        <Button onClick={onClose} variant="ghost">
          Cancel
        </Button>
        <Button disabled={!canSave || phase === "creating"} onClick={create}>
          {phase === "creating" ? <Spinner /> : null}
          {phase === "creating" ? "Creating…" : "Create token"}
        </Button>
      </DialogFooter>
    </>
  )
}

import {
  ArrowLeft02Icon,
  ClockAlertIcon,
  Copy01Icon,
  Key01Icon,
  PlusSignIcon,
  PuzzleIcon,
  ShieldBanIcon,
  Tick02Icon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

export const ConnectedAppIcon = icon(PuzzleIcon, "ConnectedAppIcon")
export const AccessTokenIcon = icon(Key01Icon, "AccessTokenIcon")

export const CreateAppIcon = icon(PlusSignIcon, "CreateAppIcon")
export const CreateTokenIcon = icon(PlusSignIcon, "CreateTokenIcon")

export const RevokeTokenIcon = icon(ShieldBanIcon, "RevokeTokenIcon")

export const CopyTokenIcon = icon(Copy01Icon, "CopyTokenIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

export const NearExpiryIcon = icon(ClockAlertIcon, "NearExpiryIcon")

export const BackToIntegrationsIcon = icon(
  ArrowLeft02Icon,
  "BackToIntegrationsIcon",
)

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  ALL_SCOPES,
  READ_ONLY_SCOPES,
  SCOPE_GROUPS,
  type Permission,
} from "@/lib/mockups/connected-apps-data"

type Preset = "read-only" | "full" | "custom"

const PRESETS: { id: Preset; label: string; help: string }[] = [
  {
    id: "read-only",
    label: "Read-only",
    help: `Every read permission — ${READ_ONLY_SCOPES.length} of ${ALL_SCOPES.length}. Can list and fetch, can change nothing.`,
  },
  {
    id: "full",
    label: "Full access",
    help: `All ${ALL_SCOPES.length} permissions. Everything this organization can do through the API.`,
  },
  {
    id: "custom",
    label: "Custom",
    help: "Pick permissions one by one.",
  },
]

export function ScopePicker({
  onChange,
  scopes,
}: {
  onChange: (scopes: Permission[]) => void
  scopes: Permission[]
}) {
  const [preset, setPreset] = React.useState<Preset>("read-only")

  function selectPreset(next: Preset) {
    setPreset(next)
    if (next === "read-only") onChange(READ_ONLY_SCOPES)
    if (next === "full") onChange(ALL_SCOPES)
  }

  function toggle(permission: Permission, granted: boolean) {
    onChange(
      granted
        ? [...scopes, permission]
        : scopes.filter((value) => value !== permission),
    )
  }

  return (
    <Field>
      {/* FieldTitle, not FieldLabel: a radio group and a checkbox grid have no single id. */}
      <FieldTitle>Scopes</FieldTitle>

      <RadioGroup
        className="gap-2"
        onValueChange={(value) => selectPreset(value as Preset)}
        value={preset}
      >
        {PRESETS.map((option) => (
          <FieldLabel htmlFor={`preset-${option.id}`} key={option.id}>
            <Field orientation="horizontal">
              <FieldContent>
                <FieldTitle>{option.label}</FieldTitle>
                <FieldDescription>{option.help}</FieldDescription>
              </FieldContent>
              <RadioGroupItem id={`preset-${option.id}`} value={option.id} />
            </Field>
          </FieldLabel>
        ))}
      </RadioGroup>

      {preset === "custom" ? (
        <div className="flex flex-col gap-3 rounded-lg bg-muted p-3">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium tabular-nums">
              {scopes.length} of {ALL_SCOPES.length} permissions
            </span>
            <Button
              className="ms-auto"
              onClick={() => onChange(READ_ONLY_SCOPES)}
              size="xs"
              variant="ghost"
            >
              All read
            </Button>
            <Button onClick={() => onChange([])} size="xs" variant="ghost">
              Clear
            </Button>
          </div>

          <ScrollArea className="h-56">
            <div className="grid grid-cols-[1fr_auto_auto] items-center gap-x-6 gap-y-2 pe-3">
              <span />
              <span className="text-xs text-muted-foreground">Read</span>
              <span className="text-xs text-muted-foreground">Write</span>

              {SCOPE_GROUPS.map((group) => (
                <React.Fragment key={group.read}>
                  <span className="text-sm">{group.label}</span>

                  {/* The exact permission string is the accessible name. */}
                  <Checkbox
                    aria-label={group.read}
                    checked={scopes.includes(group.read)}
                    onCheckedChange={(checked) =>
                      toggle(group.read, checked === true)
                    }
                  />

                  {group.write ? (
                    <Checkbox
                      aria-label={group.write}
                      checked={scopes.includes(group.write)}
                      onCheckedChange={(checked) =>
                        toggle(group.write as Permission, checked === true)
                      }
                    />
                  ) : (
                    <span />
                  )}
                </React.Fragment>
              ))}
            </div>
          </ScrollArea>

          {scopes.includes("api_keys:write") ? (
            <FieldDescription>
              A token with <span className="font-mono">api_keys:write</span> can
              create more tokens.
            </FieldDescription>
          ) : null}
        </div>
      ) : null}
    </Field>
  )
}

"use client"

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog"
import {
  DataTableHead,
  DataTableHeaderRow,
} from "@/components/shared/data-table"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import {
  daysUntil,
  formatDate,
  NEAR_EXPIRY_DAYS,
  relativeSince,
  scopeSummary,
  TOKEN_CAP,
  tokenStatus,
  type Token,
} from "@/lib/mockups/connected-apps-data"
import { RevokeTokenIcon } from "@/components/mockups/connected-apps/icons"

export function TokenTable({
  onRevoke,
  tokens,
}: {
  onRevoke: (token: Token) => void
  tokens: Token[]
}) {
  return (
    <Table className="[&_tbody_tr:last-child]:border-0 [&_td]:px-4 [&_th]:px-4">
      <TableHeader>
        <DataTableHeaderRow>
          <DataTableHead>Name</DataTableHead>
          <DataTableHead>Scopes</DataTableHead>
          <DataTableHead>Expires</DataTableHead>
          <DataTableHead>Last used</DataTableHead>
          <DataTableHead>Status</DataTableHead>
          <TableHead className="text-end font-semibold text-foreground" />
        </DataTableHeaderRow>
      </TableHeader>

      <TableBody>
        {tokens.map((token) => (
          <TokenRow key={token.id} onRevoke={onRevoke} token={token} />
        ))}
      </TableBody>
    </Table>
  )
}

function TokenRow({
  onRevoke,
  token,
}: {
  onRevoke: (token: Token) => void
  token: Token
}) {
  const status = tokenStatus(token)
  const live = status === "active"

  return (
    <TableRow className="transition-colors duration-150 ease-out-cubic hover:bg-muted/50 motion-reduce:transition-none">
      <TableCell>
        <div className="flex flex-col gap-0.5">
          <span
            className={cn("font-medium", !live && "text-muted-foreground")}
            dir="auto"
          >
            {token.name}
          </span>

          <Tooltip>
            <TooltipTrigger asChild>
              {/* Always LTR: a base64 credential reordered next to Arabic is a different string. */}
              <span
                className="w-fit font-mono text-xs text-muted-foreground"
                dir="ltr"
              >
                {token.prefix}…
              </span>
            </TooltipTrigger>
            <TooltipContent>
              The first 8 characters — all Sarj stores of this token.
            </TooltipContent>
          </Tooltip>
        </div>
      </TableCell>

      <TableCell>
        <Tooltip>
          <TooltipTrigger asChild>
            <Badge variant="outline">{scopeSummary(token.scopes)}</Badge>
          </TooltipTrigger>
          {/* The platform's scope strings, unedited. */}
          <TooltipContent className="font-mono">
            {token.scopes.join(", ")}
          </TooltipContent>
        </Tooltip>
      </TableCell>

      <TableCell>
        <ExpiryCell token={token} />
      </TableCell>

      <TableCell className="text-muted-foreground">
        {relativeSince(token.lastUsedAt)}
      </TableCell>

      <TableCell>
        <StatusBadge status={status} />
      </TableCell>

      <TableCell className="text-end">
        {status === "revoked" ? (
          <span className="text-muted-foreground">—</span>
        ) : (
          <RevokeDialog onRevoke={onRevoke} token={token} />
        )}
      </TableCell>
    </TableRow>
  )
}

function StatusBadge({ status }: { status: "active" | "expired" | "revoked" }) {
  if (status === "active") {
    return (
      <Badge
        className="bg-success-tint text-success-tint-foreground"
        variant="secondary"
      >
        Active
      </Badge>
    )
  }

  return (
    <Badge className="bg-muted text-muted-foreground" variant="secondary">
      {status === "expired" ? "Expired" : "Revoked"}
    </Badge>
  )
}

function ExpiryCell({ token }: { token: Token }) {
  if (!token.expiresAt) {
    return <span className="text-muted-foreground">Never</span>
  }

  const days = daysUntil(token.expiresAt)

  if (days > 0 && days <= NEAR_EXPIRY_DAYS) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <Badge
            className="bg-warning-tint text-warning-tint-foreground"
            variant="secondary"
          >
            In {days} {days === 1 ? "day" : "days"}
          </Badge>
        </TooltipTrigger>
        <TooltipContent>{formatDate(token.expiresAt)}</TooltipContent>
      </Tooltip>
    )
  }

  return (
    <span className="text-muted-foreground">{formatDate(token.expiresAt)}</span>
  )
}

function RevokeDialog({
  onRevoke,
  token,
}: {
  onRevoke: (token: Token) => void
  token: Token
}) {
  const expired = tokenStatus(token) === "expired"
  /* `daysUntil` is negative for a past date, so this is "used within the last week". */
  const recentlyUsed =
    token.lastUsedAt !== null && -daysUntil(token.lastUsedAt) <= 7

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>
        <Button aria-label={`Revoke ${token.name}`} size="xs" variant="outline">
          <RevokeTokenIcon />
          Revoke
        </Button>
      </AlertDialogTrigger>

      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogMedia>
            <RevokeTokenIcon />
          </AlertDialogMedia>
          <AlertDialogTitle>
            Revoke <span dir="auto">{token.name}</span>?
          </AlertDialogTitle>
          <AlertDialogDescription>
            {expired && token.expiresAt ? (
              <>
                It expired on {formatDate(token.expiresAt)} and can no longer
                authenticate, so nothing will break. Revoking frees one of your{" "}
                {TOKEN_CAP} token slots.
              </>
            ) : (
              <>
                {recentlyUsed ? (
                  <>
                    It was last used {relativeSince(token.lastUsedAt)}, so
                    something is almost certainly calling Sarj with it right
                    now.{" "}
                  </>
                ) : null}
                Anything using this token immediately loses access, and this
                cannot be undone. If it is still in production, create a
                replacement and switch over first.
              </>
            )}
          </AlertDialogDescription>
        </AlertDialogHeader>

        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction
            onClick={() => onRevoke(token)}
            variant="destructive"
          >
            Revoke token
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

